// Test 5: Door hold and safety cap
function testDoorHoldAndSafetyCap() {
    var el = new ElevatorLogic({ floorCount: 6, maxCapacity: 4, MIN_DOOR_OPEN_S: 1.0, MAX_DOOR_OPEN_S: 3.0 });
    el.callUp(0);
    runUntilDoorOpenAt(el, 0);

    // Doors should be open
    assert.strictEqual(el.getState(), STATE.DOOR_OPEN);

    // Reserve but don't complete - doors should stay open
    var s = el.reserveBoardingSpot("p1");
    assert.ok(s);

    // Tick past MIN_DOOR_OPEN_S
    for (var i = 0; i < 100; i++) {
        el.tick(0.05);
    }
    // Doors should still be open because pendingBoarderCount > 0
    assert.strictEqual(el.getState(), STATE.DOOR_OPEN, "doors should stay open with pending boarders");

    // Tick past MAX_DOOR_OPEN_S
    for (var i = 0; i < 200; i++) {
        el.tick(0.05);
    }
    // Doors should now be closing (safety cap)
    assert.strictEqual(el.getState(), STATE.DOOR_CLOSING, "doors should close after MAX_DOOR_OPEN_S");
}

