    // Tick past MIN_DOOR_OPEN_S
    for (var i = 0; i < 100; i++) {
        el.tick(0.05);
    }
    // Doors should still be open because pendingBoarderCount > 0
    assert.strictEqual(el.getState(), STATE.DOOR_OPEN, "doors should stay open with pending boarders");

    // Tick past MAX_DOOR_OPEN_S
    for (var i = 0; i < 200; i++) {
        el.tick(0.05);
    }
    // Doors should now be closing (safety cap)
    assert.strictEqual(el.getState(), STATE.DOOR_CLOSING, "doors should close after MAX_DOOR_OPEN_S");
