    // Car should reach floor 5
    runUntilDoorOpenAt(el, 5);
    assert.strictEqual(el.currentFloor, 5, "car should arrive at floor 5");
}

// Test 7: Reset clears phantom state
function testReset() {
    var el = new ElevatorLogic({ floorCount: 6, maxCapacity: 4 });
