    var dispMesh = new THREE.Mesh(dispGeo, dispMat);
    dispMesh.position.set(0, -0.45, 0.05);
    group.add(dispMesh);

    group.userData = {
        upMesh: upMesh,
        downMesh: downMesh,
        dispMesh: dispMesh,
        dispTex: dispTex,
        setUp: function(on) {
            upMesh.material.color.setHex(on ? 0x44ff44 : 0x444444);
